export function StatTiles({
  items,
  active,
  onHover,
  columns = 3,
  responsive = false,
  fillLastOdd = false,
  balanceLastRow = false,
  inactiveOpacity = 0.35,
  focusable = true,
  equalWidth = false,
  tabular = true,
  className,
}: {
  equalWidth?: boolean;
  tabular?: boolean;
  className?: string;
  items: StatTile[];
  columns?: number;
  responsive?: boolean;
  fillLastOdd?: boolean;
  balanceLastRow?: boolean;
  inactiveOpacity?: number;
  focusable?: boolean;
  active?: number | null;
  onHover?: (index: number | null) => void;
}) {
  return (
    <div
      className={cx(
        "-mx-2 -mb-1 gap-2",
        responsive
          ? "grid grid-cols-2 sm:grid-cols-[repeat(var(--stat-columns),minmax(0,1fr))]"
          : "flex flex-wrap",
        className,
      )}
      style={
        responsive
          ? ({
              "--stat-columns": balanceLastRow ? columns * 2 : columns,
            } as CSSProperties)
          : undefined
      }
    >
      {items.map((item, index) => (
        <div
          key={item.label}
          data-chart-tile={index}
          tabIndex={onHover && focusable ? 0 : undefined}
          onMouseEnter={() => onHover?.(index)}
          onMouseLeave={() => onHover?.(null)}
          onFocus={() => onHover?.(index)}
          onBlur={() => onHover?.(null)}
          className={cx(
            "flex min-w-0 flex-auto flex-col items-start gap-px rounded-2lg bg-background-inner-default px-2.5 py-2 outline-none transition-opacity duration-200 ease-out motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
            equalWidth && "flex-1 justify-end",
            responsive &&
              fillLastOdd &&
              index === items.length - 1 &&
              items.length % 2 === 1 &&
              (balanceLastRow ? "col-span-2" : "col-span-2 sm:col-span-1"),
            balanceLastRow && responsive && "sm:col-span-[var(--stat-span)]",
          )}
          style={
            {
              opacity: active != null && active !== index ? inactiveOpacity : 1,
              flexBasis: equalWidth ? 0 : responsive ? undefined : `calc(${100 / columns}% - 8px)`,
              ...(balanceLastRow && responsive
                ? {
                    "--stat-span":
                      index >= items.length - (items.length % columns) && items.length % columns
                        ? (columns * 2) / (items.length % columns)
                        : 2,
                  }
                : {}),
            } as CSSProperties
          }
        >
          <div className="flex min-w-0 max-w-full items-center gap-1.5">
            {item.color && (
              <span
                className="size-3 shrink-0 rounded-[4px] transition-colors duration-150 ease-out"
                style={{
                  background: active === index ? (item.activeColor ?? item.color) : item.color,
                }}
              />
            )}
            <span className="truncate text-body-regular text-text-secondary">{item.label}</span>
          </div>
          <span
            className={cx(
              "whitespace-nowrap text-body-medium text-text-primary",
              tabular && "tabular-nums",
            )}
          >
            {item.value}
          </span>
        </div>
      ))}
    </div>
  );
}
export function PulseDot({ cx: x, cy: y, stroke }: { cx?: number; cy?: number; stroke?: string }) {
  const reduced = useHydratedReducedMotion();
  if (x == null || y == null) return null;
  return (
    <g>
      <motion.circle
        key={reduced ? "reduced" : "animated"}
        cx={x}
        cy={y}
        fill={stroke}
        initial={false}
        animate={reduced ? { r: 7, opacity: 0.2 } : { r: [5, 11, 5], opacity: [0.25, 0, 0.25] }}
        transition={reduced ? { duration: 0 } : { duration: 1.6, repeat: Infinity }}
      />
      <circle
        cx={x}
        cy={y}
        r={3.5}
        fill={stroke}
        stroke="var(--color-background-inner-default)"
        strokeWidth={2}
      />
    </g>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};
const clientSnapshot = () => true;
const serverSnapshot = () => false;

/** Keep the first server/client render identical, then apply the user's motion preference. */
export function useHydratedReducedMotion(): boolean {
  const reduced = useReducedMotion();
  const hydrated = useSyncExternalStore(subscribe, clientSnapshot, serverSnapshot);
  return hydrated && reduced === true;
}

